import unittest
from solution import merge_closed_intervals

class T(unittest.TestCase):
    def test_overlap(self):
        self.assertEqual(merge_closed_intervals([[1, 3], [2, 6]]), [[1, 6]])
    def test_touch(self):
        self.assertEqual(merge_closed_intervals([[1, 3], [3, 5]]), [[1, 5]])
    def test_disjoint(self):
        self.assertEqual(merge_closed_intervals([[5, 6], [1, 2]]), [[1, 2], [5, 6]])
    def test_empty(self):
        self.assertEqual(merge_closed_intervals([]), [])
